// Normaliza argumentos e calcula o dia da semana (0=domingo…6=sábado) da data solicitada.
const a = $input.first().json || {};
const date = a.date || new Date().toISOString().slice(0, 10);
const barber_id = (a.barber_id === null || a.barber_id === undefined || a.barber_id === '') ? null : a.barber_id;
const dataRef = new Date(date + 'T12:00:00');
const day_of_week = dataRef.getDay();
const agora = new Date();
const hojeLocal = agora.getFullYear() + '-' + String(agora.getMonth() + 1).padStart(2, '0') + '-' + String(agora.getDate()).padStart(2, '0');
return [{ json: {
  date,
  service_id: a.service_id ?? null,
  barber_id,
  day_of_week,
  dayStartIso: date + 'T00:00:00-03:00',
  nowIso: agora.toISOString(),
  isToday: date === hojeLocal
} }];

// Regras de slots (§4): working_hours, intervalo de almoço, horários passados,
// duração do serviço e sobreposição com agendamentos ativos.
const prep = $('Preparar Parâmetros da Data').first().json;
const servico = $('Buscar Duração do Serviço').first().json || {};
const expediente = $('Buscar Expediente do Dia').first().json || null;
const agendamentos = $('Buscar Agendamentos do Dia').all().map(i => i.json);

const nomesFechado = ['Fechado aos domingos', 'Fechado às segundas-feiras', 'Fechado às terças-feiras', 'Fechado às quartas-feiras', 'Fechado às quintas-feiras', 'Fechado às sextas-feiras', 'Fechado aos sábados'];

if (!expediente) {
  return [{ json: { date: prep.date, closed: true, slots: [], reason: 'Dia sem expediente cadastrado na tabela working_hours.' } }];
}
if (expediente.closed) {
  return [{ json: { date: prep.date, closed: true, slots: [], reason: nomesFechado[expediente.day_of_week] } }];
}
function paraMinutos(t) { if (!t) return null; const p = String(t).split(':').map(Number); return p[0] * 60 + p[1]; }
const openMin = paraMinutos(expediente.open_time);
const closeMin = paraMinutos(expediente.close_time);
const breakIni = paraMinutos(expediente.break_start);
const breakFim = paraMinutos(expediente.break_end);
const step = Number(expediente.slot_interval_minutes || 30);
const duracao = Number(servico.duration_minutes || 30);
const agora = new Date(prep.nowIso);
const slots = [];
for (let t = openMin; t + duracao <= closeMin; t += step) {
  const fim = t + duracao;
  if (breakIni !== null && breakFim !== null && t < breakFim && fim > breakIni) continue;
  if (prep.isToday) {
    const agoraMin = agora.getHours() * 60 + agora.getMinutes();
    if (t <= agoraMin) continue;
  }
  let ocupado = false;
  for (const a of agendamentos) {
    if (prep.barber_id && a.barber_id && Number(a.barber_id) !== Number(prep.barber_id)) continue;
    const s = new Date(a.start_at); const e = new Date(a.end_at);
    const sMin = s.getHours() * 60 + s.getMinutes();
    const eMin = e.getHours() * 60 + e.getMinutes();
    if (t < eMin && fim > sMin) { ocupado = true; break; }
  }
  if (ocupado) continue;
  const hh = String(Math.floor(t / 60)).padStart(2, '0');
  const mm = String(t % 60).padStart(2, '0');
  slots.push(hh + ':' + mm);
}
return [{ json: { date: prep.date, closed: false, slots, reason: null } }];
